-- Replace non-assessment editorial statements with topic-specific authorial checks.
WITH replacements(slug,new_quiz) AS (VALUES
('administrativo-acervo-atos','[{"q":"Motivo e motivação são expressões sinônimas no estudo dos atos administrativos.","a":false,"why":"Errado. Motivo é o pressuposto de fato e de direito do ato; motivação é a exposição das razões que justificam sua prática."},{"q":"Um ato administrativo ilegal pode ser anulado, enquanto a revogação incide, em regra, sobre ato válido por conveniência e oportunidade.","a":true,"why":"Correto. Anulação relaciona-se à legalidade; revogação ao mérito administrativo, dentro dos limites jurídicos."}]'::jsonb),
('administrativo-acervo-controle','[{"q":"O controle interno é exercido no âmbito da própria estrutura administrativa.","a":true,"why":"Correto. O controle interno é realizado dentro do Poder ou órgão; o controle externo tem estrutura e titularidade distintas."},{"q":"A revogação é o instrumento adequado para retirar um ato exclusivamente porque ele nasceu ilegal.","a":false,"why":"Errado. A ilegalidade fundamenta anulação; revogação pressupõe ato válido e avaliação de conveniência e oportunidade."}]'::jsonb),
('administrativo-acervo-fundamentos-organizacao','[{"q":"A desconcentração distribui competências entre órgãos de uma mesma pessoa jurídica.","a":true,"why":"Correto. A desconcentração organiza atribuições internamente; a descentralização envolve outra pessoa ou delegação da execução."},{"q":"Todo órgão público da Administração Direta possui personalidade jurídica própria.","a":false,"why":"Errado. Órgãos integram a pessoa jurídica a que pertencem; não possuem, em regra, personalidade jurídica própria."}]'::jsonb),
('administrativo-acervo-lei-9784','[{"q":"A Lei nº 9.784/1999 disciplina, em regra, o processo administrativo no âmbito da Administração Pública federal.","a":true,"why":"Correto. O diploma estabelece normas gerais do processo administrativo federal e contempla princípios como motivação, razoabilidade e contraditório."},{"q":"A avocação de competência é sempre definitiva e dispensa justificativa.","a":false,"why":"Errado. A avocação prevista na Lei nº 9.784/1999 é excepcional, temporária e deve ser justificada por motivos relevantes."}]'::jsonb),
('administrativo-acervo-poderes','[{"q":"O poder discricionário autoriza o agente público a agir arbitrariamente, sem limites legais.","a":false,"why":"Errado. A discricionariedade permite escolhas dentro dos limites legais; arbitrariedade é atuação contrária ao direito."},{"q":"O poder hierárquico permite distribuir e organizar funções no âmbito da estrutura administrativa.","a":true,"why":"Correto. A hierarquia organiza a atuação administrativa, incluindo distribuição de atribuições e mecanismos de supervisão."}]'::jsonb),
('administrativo-acervo-responsabilidade','[{"q":"A responsabilidade objetiva do Estado significa que toda e qualquer situação de dano gera indenização, independentemente do nexo causal.","a":false,"why":"Errado. A responsabilidade objetiva não dispensa dano e nexo causal, e o regime de risco administrativo admite hipóteses de exclusão ou atenuação."},{"q":"O direito de regresso contra o agente público, no art. 37, § 6º, da Constituição, exige dolo ou culpa do agente.","a":true,"why":"Correto. A responsabilidade perante o terceiro e a responsabilidade regressiva do agente têm pressupostos distintos; a ação regressiva exige dolo ou culpa."}]'::jsonb)
)
UPDATE public.study_materials sm SET quiz=r.new_quiz,
practice_review=jsonb_set(coalesce(sm.practice_review,'{}'::jsonb),'{quiz_placeholder_audit}',jsonb_build_object('status','replaced_with_topic_questions_pending_independent_legal_review','checked_at','2026-11-21'),true),updated_at=now()
FROM replacements r WHERE sm.slug=r.slug AND jsonb_array_length(sm.quiz)=1
AND sm.quiz->0->>'q'='O conteúdo desta trilha foi organizado a partir dos materiais enviados e revisado para a legislação vigente.';
-- Flag unrelated accounting insertions for targeted editorial cleanup; do not silently remove possibly mixed content.
UPDATE public.study_materials SET
practice_review=jsonb_set(coalesce(practice_review,'{}'::jsonb),'{cross_discipline_contamination}',jsonb_build_object('status','requires_section_level_review','detected_heading','Classificação dos passivos financeiros — CPC 26','checked_at','2026-11-21'),true),updated_at=now()
WHERE content_status='active' AND discipline NOT ILIKE '%Contab%'
AND body_md LIKE '%## Classificação dos passivos financeiros — CPC 26%';